positions = [(r, c) for r in range(24) for c in range(27) if grid[r][c] == 5]

# Main diagonal check (r == c)
main_diag = [(r, c) for r, c in positions if r == c and c < 27]
# Anti-diagonal check (r + c == constant)
anti_diag_lines = {}
for r, c in positions:
    s = r + c
    if s not in anti_diag_lines:
        anti_diag_lines[s] = []
    anti_diag_lines[s].append((r, c))

print(f"5s on main diagonal (r=c): {main_diag}")
print(f"5s on anti-diagonals (r+c=const) with >5 cells:")
for s in sorted(anti_diag_lines.keys(), key=lambda x: -len(anti_diag_lines[x]))[:10]:
    print(f"  r+c={s}: {len(anti_diag_lines[s])} cells at {anti_diag_lines[s]}")

# Check for patterns at regular intervals
print("\n\nChecking diagonal patterns (r-c=const):")
diag_deltas = {}
for r, c in positions:
    d = r - c
    if d not in diag_deltas:
        diag_deltas[d] = []
    diag_deltas[d].append((r, c))

# Find diagonals with regular spacing
for d in sorted(diag_deltas.keys(), key=lambda x: -len(diag_deltas[x]))[:10]:
    pts = diag_deltas[d]
    pts_sorted = sorted(pts, key=lambda x: x[0])
    print(f"  r-c={d}: {pts_sorted[:5]}... (total {len(pts_sorted)})")
    if len(pts_sorted) >= 4:
        # Check if equally spaced
        diffs = [pts_sorted[i+1][0] - pts_sorted[i][0] for i in range(len(pts_sorted)-1)]
        if len(set(diffs)) == 1:
            print(f"    -> Equally spaced with step {diffs[0]}")
